    for (Event event : events) {
      sb.append(event.toString()).append("\n");
      sb.append("  Data: ").append(event.getData()).append("\n");
    }

    return sb.toString();
  }

  @Override
  public String toString() {
    return String.format("EventStore{events=%d}", events.size());
  }
}

